suppressPackageStartupMessages({library(data.table);library(Matrix);library(jsonlite)});setDTthreads(2)
BASE='almanac_conditionals/state_conditioned_bridge/program_first';OUT=file.path(BASE,'results');ART=file.path(BASE,'artifacts');OLD='almanac_conditionals/state_conditioned_bridge/sensitivity_selected';old=readRDS(file.path(OLD,'prepared.rds'));g=readRDS(file.path(OLD,'artifacts/eligible_gene_measurements.rds'));w=fread(file.path(OUT,'frozen_program_weights.tsv'));genes=fread(file.path(OUT,'selected_gene_universe.tsv'))$gene;P=sort(unique(w$program));freeze=fromJSON(file.path(OUT,'program_bank_freeze.json'));stopifnot(!freeze$sensitivity_used,!freeze$AU565_used,setequal(w$gene,genes),!anyDuplicated(w$gene),!'ACH-000248'%in%g$metadata$depmap_id)
W=sparseMatrix(i=match(w$gene,genes),j=match(w$program,P),x=w$weight,dims=c(length(genes),length(P)),dimnames=list(genes,P));scores=as.matrix(g$response[,genes,drop=F]%*%W);base=as.matrix(g$baseline[,genes,drop=F]%*%W);m=copy(g$metadata);m[,(P):=as.data.table(scores)];controls=cbind(data.table(depmap_id=rownames(g$baseline)),as.data.table(base));fd=old$fd[depmap_id!='ACH-000248'];res=list();audit=list()
for(dr in unique(m$drug)){ids=sort(unique(m$depmap_id));A=matrix(0,length(ids),length(P),dimnames=list(ids,P));for(k in 1:3){ix=which(m$drug==dr&m$dose==c(.05,.5,5)[k]);A=A+c(.25,.5,.25)[k]*scores[ix[match(ids,m$depmap_id[ix])],,drop=F]};outcome=fd[drug==dr&dose==2.5];y=100-100*2^outcome$y[match(ids,outcome$depmap_id)];known=is.finite(y);stopifnot(sum(known)==33);r=as.numeric(cor(A[known,,drop=F],y[known]));pv=2*pt(-abs(r)*sqrt((sum(known)-2)/pmax(1-r*r,.Machine$double.eps)),sum(known)-2);res[[dr]]=data.table(drug=dr,program=P,n=sum(known),r,p=pv);audit[[dr]]=data.table(drug=dr,depmap_id=ids,sensitivity=y,used_for_selection=known);for(j in seq_along(P)){ct=cor.test(A[known,j],y[known]);stopifnot(abs(unname(ct$estimate)-r[j])<1e-10,abs(ct$p.value-pv[j])<1e-10)}}
r=rbindlist(res);r[,q:=p.adjust(p,'BH')];r[,associated:=is.finite(q)&q<.05];r[,fdr_family:=sprintf('%d programs x 2 focal drugs; both signs',length(P))];keep=P[P%in%r[associated==TRUE,program]];r[,selected_for_any_drug:=program%in%keep];fwrite(r,file.path(OUT,'program_sensitivity_associations.tsv'),sep='\t');fwrite(rbindlist(audit),file.path(OUT,'association_line_audit.tsv'),sep='\t');fwrite(data.table(program=P,selected= P%in%keep),file.path(OUT,'program_selection.tsv'),sep='\t');fwrite(w[program%in%keep],file.path(OUT,'selected_program_weights.tsv'),sep='\t')
p=list(m=m,controls=controls,fd=fd,receptors=old$receptors,W=as.matrix(W),program_version='all_eligible_program_first',selected_programs=keep,scope='Unsupervised program discovery followed by sensitivity association selection; exploratory post-selection analysis');saveRDS(p,file.path(BASE,'all_programs_prepared.rds'));if(length(keep)){p$m=p$m[,c('sample_id','depmap_id','drug','dose','contributing_plates',keep),with=F];p$controls=p$controls[,c('depmap_id',keep),with=F];p$W=p$W[,keep,drop=F];saveRDS(p,file.path(BASE,'prepared.rds'))}
fwrite(m,file.path(OUT,'all_program_displacements.tsv'),sep='\t');fwrite(controls,file.path(OUT,'all_program_baseline.tsv'),sep='\t');fwrite(w[order(program,-absolute_weight),.(genes=.N,top_genes=paste(head(gene,12),collapse=', ')),by=program],file.path(OUT,'program_gene_summary.tsv'),sep='\t')
# Post-freeze representation audit: neither HGF nor sensitivity changes discovery or rank.
hg=readRDS(file.path(OLD,'bridge/artifacts/hgf_eligible_gene_audit.rds'));H=hg$H[,genes,drop=F];h=colMeans(H);retain=function(V){if(!ncol(V))return(0);project=as.numeric(V%*%solve(crossprod(V),crossprod(V,h)));sum(project^2)/sum(h*h)};wd=as.matrix(W);ha=data.table(stage=c('eligible genes','full program bank','selected programs'),programs=c(NA_integer_,length(P),length(keep)),HGF_energy_fraction=c(1,retain(wd),retain(wd[,keep,drop=F])));fwrite(ha,file.path(OUT,'hgf_capture_audit.tsv'),sep='\t')
# Measure observed crizotinib/HGF direction before and after each representation step.
ii=which(m$drug=='crizotinib'&m$dose==.5);D=g$response[ii,genes,drop=F];opposition=function(X,z)-as.numeric(X%*%z)/sqrt(rowSums(X*X)*sum(z*z));trace=list(data.table(stage='eligible genes',mean_reversal_cosine=mean(opposition(D,h)),opposing_HGF_lines=sum(opposition(D,h)>0),lines=nrow(D)));for(stage in c('full program bank','selected programs')){V=wd[,if(stage=='full program bank')P else keep,drop=F];if(!ncol(V))next;B=solve(crossprod(V),t(V));HP=as.numeric(h%*%V%*%B);DP=as.matrix(D%*%V)%*%B;co=opposition(DP,HP);trace[[stage]]=data.table(stage,mean_reversal_cosine=mean(co),opposing_HGF_lines=sum(co>0),lines=nrow(D))};fwrite(rbindlist(trace),file.path(OUT,'crizotinib_hgf_direction_audit.tsv'),sep='\t')
# Wilson exclusion across all actual discovery and association records.
tahoe=fread(file.path(OUT,'full_tahoe_profile_metadata.tsv.gz'));cyto=fread(file.path(OUT,'cytosig_discovery_metadata.tsv'));hasAU=function(x)sum(grepl('AU[ _-]?565|ACH-000248',as.character(unlist(x)),ignore.case=T));ex=data.table(stage=c('Tahoe discovery','CytoSig discovery identifiers','association recipients'),AU565_records=c(hasAU(tahoe),hasAU(cyto),hasAU(rbindlist(audit))));stopifnot(all(ex$AU565_records==0));fwrite(ex,file.path(OUT,'wilson_exclusion_audit.tsv'),sep='\t');print(r[associated==TRUE][order(drug,q)]);print(ha);cat('Frozen bank:',length(P),'programs; selected union:',length(keep),'\n')
# These post-freeze diagnostics localize compression versus selection loss.
ret=list();for(dr in unique(m$drug)){ids=sort(unique(m$depmap_id));X=matrix(0,length(ids),length(genes));for(k in 1:3){ix=which(m$drug==dr&m$dose==c(.05,.5,5)[k]);X=X+c(.25,.5,.25)[k]*g$response[ix[match(ids,m$depmap_id[ix])],genes,drop=F]};outcome=fd[drug==dr&dose==2.5];y=100-100*2^outcome$y[match(ids,outcome$depmap_id)];known=is.finite(y);cv=as.numeric(cov(X[known,,drop=F],y[known]));for(stage in c('full program bank','selected programs')){V=wd[,if(stage=='full program bank')P else keep,drop=F];projection=if(ncol(V))as.numeric(V%*%solve(crossprod(V),crossprod(V,cv))) else rep(0,length(cv));ret[[paste(dr,stage)]]=data.table(drug=dr,stage,n=sum(known),covariance_energy_fraction=sum(projection^2)/sum(cv^2),interpretation='In-sample covariance direction capture within the complete eligible gene universe; not predictive validation')}}
fwrite(rbindlist(ret),file.path(OUT,'sensitivity_direction_retention.tsv'),sep='\t')
contexts=list();for(stage in c('full program bank','selected programs')){V=wd[,if(stage=='full program bank')P else keep,drop=F];project=if(ncol(V))H%*%V%*%solve(crossprod(V),t(V)) else H*0;contexts[[stage]]=data.table(stage,context=if(is.null(rownames(H)))as.character(seq_len(nrow(H))) else rownames(H),HGF_energy_fraction=rowSums(project^2)/rowSums(H^2))};fwrite(rbindlist(contexts),file.path(OUT,'hgf_context_capture_audit.tsv'),sep='\t')
